PandaConquest = PandaConquest or {}

local PC = PandaConquest
local Skin = {}

PC.Skin = Skin

-- Textured widgets built from the sprite atlas (data/ui_atlas.lua, generated by
-- tools/build_ui_atlas.py). A piece is drawn at the size the caller gives; a
-- sliced piece keeps its caps' proportions and stretches its middle. Only local
-- drawing: nothing here reads or sends game data.
local COLORS = {
  H = { 0.90, 0.25, 0.20 }, A = { 0.25, 0.55, 1.00 }, N = { 0.70, 0.70, 0.70 },
  GOOD = { 0.30, 1.00, 0.30 }, BAD = { 1.00, 0.35, 0.35 }, DIM = { 0.60, 0.60, 0.60 },
  GOLD = { 1.00, 0.82, 0.00 }, WHITE = { 1.00, 1.00, 1.00 },
}

Skin.COLORS = COLORS

local function GetGlobal(name)
  if getglobal then return getglobal(name) end
  if _G then return _G[name] end
  return nil
end

local function Atlas()
  return PC.UIAtlas
end

function Skin:Piece(name)
  local atlas = Atlas()
  return atlas and atlas.pieces[name]
end

-- Applies the part (x0..x1, y0..y1, in the piece's pixels) of a single-tile piece.
function Skin:Apply(texture, name, x0, x1, y0, y1)
  local atlas = Atlas()
  local piece = atlas and atlas.pieces[name]
  if not texture or not piece or piece.tiles then return false end
  local size = atlas.page
  x0, x1 = x0 or 0, x1 or piece.w
  y0, y1 = y0 or 0, y1 or piece.h
  texture:SetTexture(atlas.pages[piece.p])
  texture:SetTexCoord((piece.x + x0) / size, (piece.x + x1) / size, (piece.y + y0) / size, (piece.y + y1) / size)
  return true
end

-- A plain texture showing a whole single-tile piece.
function Skin:Icon(parent, name, width, height, layer)
  local texture = parent:CreateTexture(nil, layer or "ARTWORK")
  texture:SetWidth(width)
  texture:SetHeight(height or width)
  if name then self:Apply(texture, name) end
  return texture
end

-- A fixed piece of any size (large ornaments are cut in tiles): a frame holding
-- one texture per tile, placed by the caller.
function Skin:Image(parent, name, width, height, layer)
  local create = GetGlobal("CreateFrame")
  local frame = create("Frame", nil, parent)
  frame:SetWidth(width)
  frame:SetHeight(height)
  local piece = self:Piece(name)
  if not piece then return frame end
  local tiles = piece.tiles or { { p = piece.p, x = piece.x, y = piece.y, w = piece.w, h = piece.h, ox = 0, oy = 0 } }
  local atlas = Atlas()
  local sx, sy = width / piece.w, height / piece.h
  local index = 1
  while index <= table.getn(tiles) do
    local tile = tiles[index]
    local texture = frame:CreateTexture(nil, layer or "ARTWORK")
    texture:SetTexture(atlas.pages[tile.p])
    texture:SetTexCoord(tile.x / atlas.page, (tile.x + tile.w) / atlas.page, tile.y / atlas.page, (tile.y + tile.h) / atlas.page)
    texture:SetWidth(tile.w * sx)
    texture:SetHeight(tile.h * sy)
    texture:SetPoint("TOPLEFT", frame, "TOPLEFT", tile.ox * sx, -tile.oy * sy)
    index = index + 1
  end
  return frame
end

-- Horizontal three-slice filling `frame` (height given): caps keep the
-- piece's proportions, the middle stretches. Returns { L, M, R }.
function Skin:Slice3(frame, name, height, layer)
  local slice = { L = frame:CreateTexture(nil, layer or "BORDER"), M = frame:CreateTexture(nil, layer or "BORDER"),
    R = frame:CreateTexture(nil, layer or "BORDER"), height = height }
  slice.L:SetPoint("TOPLEFT", frame, "TOPLEFT", 0, 0)
  slice.L:SetPoint("BOTTOMLEFT", frame, "BOTTOMLEFT", 0, 0)
  slice.R:SetPoint("TOPRIGHT", frame, "TOPRIGHT", 0, 0)
  slice.R:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", 0, 0)
  slice.M:SetPoint("TOPLEFT", slice.L, "TOPRIGHT", 0, 0)
  slice.M:SetPoint("BOTTOMRIGHT", slice.R, "BOTTOMLEFT", 0, 0)
  self:SetSlice3(slice, name)
  return slice
end

function Skin:SetSlice3(slice, name)
  local piece = self:Piece(name)
  if not piece or slice.name == name then return end
  slice.name = name
  local insets = piece.insets or { 0, 0, 0, 0 }
  local scale = slice.height / piece.h
  slice.L:SetWidth(math.max(1, insets[1] * scale))
  slice.R:SetWidth(math.max(1, insets[2] * scale))
  self:Apply(slice.L, name, 0, insets[1])
  self:Apply(slice.M, name, insets[1], piece.w - insets[2])
  self:Apply(slice.R, name, piece.w - insets[2], piece.w)
end

-- Vertical three-slice filling `frame` (width given), with top and bottom
-- caps of capTop and capBottom source pixels.
function Skin:Slice3V(frame, name, width, capTop, capBottom, layer)
  local piece = self:Piece(name)
  local T, M, B = frame:CreateTexture(nil, layer or "BORDER"), frame:CreateTexture(nil, layer or "BORDER"),
    frame:CreateTexture(nil, layer or "BORDER")
  if not piece then return { T = T, M = M, B = B } end
  local scale = width / piece.w
  T:SetHeight(capTop * scale)
  B:SetHeight(capBottom * scale)
  T:SetPoint("TOPLEFT", frame, "TOPLEFT", 0, 0)
  T:SetPoint("TOPRIGHT", frame, "TOPRIGHT", 0, 0)
  B:SetPoint("BOTTOMLEFT", frame, "BOTTOMLEFT", 0, 0)
  B:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", 0, 0)
  M:SetPoint("TOPLEFT", T, "BOTTOMLEFT", 0, 0)
  M:SetPoint("BOTTOMRIGHT", B, "TOPRIGHT", 0, 0)
  self:Apply(T, name, 0, piece.w, 0, capTop)
  self:Apply(M, name, 0, piece.w, capTop, piece.h - capBottom)
  self:Apply(B, name, 0, piece.w, piece.h - capBottom, piece.h)
  return { T = T, M = M, B = B }
end

-- Nine-slice filling `frame`, corners drawn at `scale` game pixels per source pixel.
function Skin:Slice9(frame, name, scale, layer)
  local piece = self:Piece(name)
  local parts = {}
  if not piece then return parts end
  local l, r, t, b = piece.insets[1], piece.insets[2], piece.insets[3], piece.insets[4]
  local xs = { 0, l, piece.w - r, piece.w }
  local ys = { 0, t, piece.h - b, piece.h }
  local keys = { "TL", "T", "TR", "L", "C", "R", "BL", "B", "BR" }
  local row = 1
  while row <= 3 do
    local column = 1
    while column <= 3 do
      local texture = frame:CreateTexture(nil, layer or "BORDER")
      self:Apply(texture, name, xs[column], xs[column + 1], ys[row], ys[row + 1])
      parts[keys[(row - 1) * 3 + column]] = texture
      column = column + 1
    end
    row = row + 1
  end
  local TL, TR, BL, BR = parts.TL, parts.TR, parts.BL, parts.BR
  TL:SetWidth(l * scale) TL:SetHeight(t * scale) TL:SetPoint("TOPLEFT", frame, "TOPLEFT", 0, 0)
  TR:SetWidth(r * scale) TR:SetHeight(t * scale) TR:SetPoint("TOPRIGHT", frame, "TOPRIGHT", 0, 0)
  BL:SetWidth(l * scale) BL:SetHeight(b * scale) BL:SetPoint("BOTTOMLEFT", frame, "BOTTOMLEFT", 0, 0)
  BR:SetWidth(r * scale) BR:SetHeight(b * scale) BR:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", 0, 0)
  parts.T:SetPoint("TOPLEFT", TL, "TOPRIGHT", 0, 0) parts.T:SetPoint("BOTTOMRIGHT", TR, "BOTTOMLEFT", 0, 0)
  parts.B:SetPoint("TOPLEFT", BL, "TOPRIGHT", 0, 0) parts.B:SetPoint("BOTTOMRIGHT", BR, "BOTTOMLEFT", 0, 0)
  parts.L:SetPoint("TOPLEFT", TL, "BOTTOMLEFT", 0, 0) parts.L:SetPoint("BOTTOMRIGHT", BL, "TOPRIGHT", 0, 0)
  parts.R:SetPoint("TOPLEFT", TR, "BOTTOMLEFT", 0, 0) parts.R:SetPoint("BOTTOMRIGHT", BR, "TOPRIGHT", 0, 0)
  parts.C:SetPoint("TOPLEFT", TL, "BOTTOMRIGHT", 0, 0) parts.C:SetPoint("BOTTOMRIGHT", BR, "TOPLEFT", 0, 0)
  return parts
end

-- A frame border made of a kit: top and bottom bars whose caps are the corner
-- blocks, side columns lined up under the corners, and a stretched centre.
-- kit = { top, bottom, left, right, centre, sideCap }, all drawn at `scale`.
function Skin:Border(frame, kit, scale)
  local create = GetGlobal("CreateFrame")
  local top, bottom = self:Piece(kit.top), self:Piece(kit.bottom)
  local left = self:Piece(kit.left)
  if not top or not bottom or not left then return nil end
  local border = { scale = scale }
  local topHeight, bottomHeight = top.h * scale, bottom.h * scale
  local sideWidth = left.w * scale
  local centre = frame:CreateTexture(nil, "BACKGROUND")
  self:Apply(centre, kit.centre)
  centre:SetPoint("TOPLEFT", frame, "TOPLEFT", sideWidth * 0.5, -topHeight * 0.5)
  centre:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", -sideWidth * 0.5, bottomHeight * 0.5)
  border.centre = centre
  local overlap = (kit.overlap or 0) * scale
  local holder = {}
  local keys = { "left", "right" }
  local index = 1
  while index <= 2 do
    local key = keys[index]
    local column = create("Frame", nil, frame)
    column:SetWidth(sideWidth)
    if key == "left" then
      column:SetPoint("TOPLEFT", frame, "TOPLEFT", 0, -topHeight + overlap)
      column:SetPoint("BOTTOMLEFT", frame, "BOTTOMLEFT", 0, bottomHeight - overlap)
    else
      column:SetPoint("TOPRIGHT", frame, "TOPRIGHT", 0, -topHeight + overlap)
      column:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", 0, bottomHeight - overlap)
    end
    self:Slice3V(column, kit[key], sideWidth, kit.sideCap or 0, kit.sideCap or 0, "BORDER")
    holder[key] = column
    index = index + 1
  end
  local bar = create("Frame", nil, frame)
  bar:SetHeight(topHeight)
  bar:SetPoint("TOPLEFT", frame, "TOPLEFT", 0, 0)
  bar:SetPoint("TOPRIGHT", frame, "TOPRIGHT", 0, 0)
  self:Slice3(bar, kit.top, topHeight, "ARTWORK")
  holder.top = bar
  bar = create("Frame", nil, frame)
  bar:SetHeight(bottomHeight)
  bar:SetPoint("BOTTOMLEFT", frame, "BOTTOMLEFT", 0, 0)
  bar:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", 0, 0)
  self:Slice3(bar, kit.bottom, bottomHeight, "ARTWORK")
  holder.bottom = bar
  border.parts = holder
  return border
end

-- Text ------------------------------------------------------------------------

function Skin:Text(parent, template, justify, layer)
  local text = parent:CreateFontString(nil, layer or "OVERLAY", template or "GameFontHighlightSmall")
  text:SetJustifyH(justify or "LEFT")
  return text
end

function Skin:Color(text, key)
  local color = COLORS[key] or COLORS.WHITE
  text:SetTextColor(color[1], color[2], color[3])
end

-- Buttons ---------------------------------------------------------------------

local BUTTON_STYLES = {
  dark = { normal = "button.normal", pushed = "button.pushed", disabled = "button.disabled", hover = "button.hover" },
  red = { normal = "redbutton.normal", pushed = "redbutton.pushed", disabled = "redbutton.disabled", hover = "redbutton.hover" },
  tab = { normal = "tab.normal", pushed = "tab.selected", disabled = "tab.normal", hover = "tab.hover", selected = "tab.selected" },
}

local function ButtonFace(button)
  local style = BUTTON_STYLES[button.style]
  local state = "normal"
  if not button.enabled then
    state = "disabled"
  elseif button.selected and style.selected then
    state = "selected"
  elseif button.down then
    state = "pushed"
  end
  Skin:SetSlice3(button.face, style[state])
  if not button.enabled then
    Skin:Color(button.label, "DIM")
  elseif button.style == "tab" and not button.selected then
    Skin:Color(button.label, "GOLD")
  else
    Skin:Color(button.label, button.textColor or "GOLD")
  end
end

-- A button with a three-slice face for each state, a glow on mouse-over and
-- its own label. onClick(button) runs only while enabled.
function Skin:Button(parent, style, width, height, onClick, name)
  local create = GetGlobal("CreateFrame")
  local button = create("Button", name, parent)
  button:SetWidth(width)
  button:SetHeight(height)
  button.style = style
  button.enabled = true
  button.face = self:Slice3(button, BUTTON_STYLES[style].normal, height, "BACKGROUND")
  local glow = self:Slice3(button, BUTTON_STYLES[style].hover, height, "HIGHLIGHT")
  glow.L:SetBlendMode("ADD")
  glow.M:SetBlendMode("ADD")
  glow.R:SetBlendMode("ADD")
  button.glow = glow
  button.label = self:Text(button, style == "tab" and "GameFontNormal" or "GameFontNormalSmall", "CENTER")
  button.label:SetPoint("CENTER", button, "CENTER", 0, style == "tab" and -1 or 0)
  button.onClick = onClick
  button:SetScript("OnMouseDown", function() if this.enabled then this.down = true ButtonFace(this) end end)
  button:SetScript("OnMouseUp", function() this.down = nil ButtonFace(this) end)
  button:SetScript("OnClick", function() if this.enabled and this.onClick then this.onClick(this) end end)
  ButtonFace(button)
  return button
end

function Skin:SetButton(button, text, enabled, selected)
  if button.text ~= text then
    button.text = text
    button.label:SetText(text)
  end
  enabled = enabled ~= false
  selected = selected and true or false
  if button.enabled == enabled and button.selected == selected then return end
  button.enabled, button.selected = enabled, selected
  if enabled then button:Enable() else button:Disable() end
  ButtonFace(button)
end

-- The close button: whole-button pieces for normal, pushed and mouse-over.
function Skin:CloseButton(parent, size, onClick)
  local create = GetGlobal("CreateFrame")
  local button = create("Button", nil, parent)
  button:SetWidth(size)
  button:SetHeight(size)
  local normal = self:Icon(button, "close.normal", size, size, "ARTWORK")
  normal:SetPoint("CENTER", button, "CENTER", 0, 0)
  local hover = self:Icon(button, "close.hover", size * 1.1, size * 1.1, "HIGHLIGHT")
  hover:SetPoint("CENTER", button, "CENTER", 0, 0)
  button:SetScript("OnMouseDown", function() Skin:Apply(normal, "close.pushed") end)
  button:SetScript("OnMouseUp", function() Skin:Apply(normal, "close.normal") end)
  button:SetScript("OnClick", function() if onClick then onClick() end end)
  return button
end

-- Bars ------------------------------------------------------------------------

-- A progress bar: frame three-slice and a fill of one colour (grey, gold,
-- brown, red, blue or green) drawn over `fraction` of the inside.
function Skin:Bar(parent, width, height, colour)
  local create = GetGlobal("CreateFrame")
  local bar = create("Frame", nil, parent)
  bar:SetWidth(width)
  bar:SetHeight(height)
  self:Slice3(bar, "bar.frame", height, "BORDER")
  local inset = math.floor(height * 0.25 + 0.5)
  bar.inner = width - 2 * inset
  bar.fill = bar:CreateTexture(nil, "ARTWORK")
  bar.fill:SetPoint("TOPLEFT", bar, "TOPLEFT", inset, -inset)
  bar.fill:SetHeight(height - 2 * inset)
  self:SetBar(bar, 0, colour or "gold")
  return bar
end

function Skin:SetBar(bar, fraction, colour)
  if colour and bar.colour ~= colour then
    bar.colour = colour
    self:Apply(bar.fill, "fill." .. colour)
  end
  if type(fraction) ~= "number" or fraction ~= fraction then fraction = 0 end
  if fraction > 1 then fraction = 1 end
  if fraction <= 0 then
    bar.fill:Hide()
    return
  end
  bar.fill:SetWidth(bar.inner * fraction)
  bar.fill:Show()
end

-- The Alliance (blue, left) against Horde (red, right) balance bar with its
-- crest caps and the crossed swords at the split.
function Skin:Balance(parent, width, height)
  local create = GetGlobal("CreateFrame")
  local bar = create("Frame", nil, parent)
  bar:SetWidth(width)
  bar:SetHeight(height)
  local cap = height * 1.25
  local track = create("Frame", nil, bar)
  track:SetPoint("TOPLEFT", bar, "TOPLEFT", cap * 0.8, -height * 0.15)
  track:SetPoint("BOTTOMRIGHT", bar, "BOTTOMRIGHT", -cap * 0.8, height * 0.15)
  local trackHeight = height * 0.7
  self:Slice3(track, "balance.frame", trackHeight, "BORDER")
  bar.track = track
  bar.inner = width - 2 * cap * 0.8 - trackHeight * 0.5
  local inset = trackHeight * 0.22
  bar.blue = track:CreateTexture(nil, "ARTWORK")
  self:Apply(bar.blue, "fill.blue")
  bar.blue:SetPoint("TOPLEFT", track, "TOPLEFT", trackHeight * 0.25, -inset)
  bar.blue:SetHeight(trackHeight - 2 * inset)
  bar.red = track:CreateTexture(nil, "ARTWORK")
  self:Apply(bar.red, "fill.red")
  bar.red:SetPoint("TOPRIGHT", track, "TOPRIGHT", -trackHeight * 0.25, -inset)
  bar.red:SetHeight(trackHeight - 2 * inset)
  local left = self:Icon(bar, "balance.left", cap, cap, "OVERLAY")
  left:SetPoint("LEFT", bar, "LEFT", 0, 0)
  local right = self:Icon(bar, "balance.right", cap, cap, "OVERLAY")
  right:SetPoint("RIGHT", bar, "RIGHT", 0, 0)
  local marker = create("Frame", nil, bar)
  local sword = height * 0.7
  marker:SetWidth(sword)
  marker:SetHeight(sword)
  marker:SetFrameLevel((bar:GetFrameLevel() or 0) + 2)
  self:Icon(marker, "crest.swords", sword, sword, "OVERLAY"):SetPoint("CENTER", marker, "CENTER", 0, 0)
  bar.marker = marker
  -- Faction crests sit in their own frame above the swords marker so the
  -- swords never hide them at either end.
  local crests = create("Frame", nil, bar)
  crests:SetAllPoints(bar)
  crests:SetFrameLevel((bar:GetFrameLevel() or 0) + 4)
  local size = cap * 1.0
  local crest = self:Icon(crests, "crest.alliance", size, size, "OVERLAY")
  crest:SetPoint("CENTER", left, "CENTER", -cap * 0.04, 0)
  crest = self:Icon(crests, "crest.horde", size, size, "OVERLAY")
  crest:SetPoint("CENTER", right, "CENTER", cap * 0.04, 0)
  self:SetBalance(bar, 1, 1)
  return bar
end

-- alliance and horde are shares (counts or percents); nothing known splits evenly.
function Skin:SetBalance(bar, alliance, horde)
  local total = (alliance or 0) + (horde or 0)
  local share = 0.5
  if total > 0 then share = alliance / total end
  local blue = bar.inner * share
  bar.blue:SetWidth(math.max(1, blue))
  bar.red:SetWidth(math.max(1, bar.inner - blue))
  if share <= 0 then bar.blue:Hide() else bar.blue:Show() end
  if share >= 1 then bar.red:Hide() else bar.red:Show() end
  bar.marker:ClearAllPoints()
  bar.marker:SetPoint("CENTER", bar.blue, "RIGHT", 0, 0)
end

-- Panels ----------------------------------------------------------------------

-- A section panel with its gold header strip and title; content goes below
-- HEADER pixels.
Skin.HEADER = 20

function Skin:Panel(parent, title, width, height)
  local create = GetGlobal("CreateFrame")
  local panel = create("Frame", nil, parent)
  panel:SetWidth(width)
  panel:SetHeight(height)
  panel.width = width
  self:Slice9(panel, "panel", 0.25, "BACKGROUND")
  local strip = create("Frame", nil, panel)
  strip:SetHeight(self.HEADER)
  strip:SetPoint("TOPLEFT", panel, "TOPLEFT", 3, -3)
  strip:SetPoint("TOPRIGHT", panel, "TOPRIGHT", -3, -3)
  self:Slice3(strip, "header", self.HEADER, "BORDER")
  panel.title = self:Text(strip, "GameFontNormal")
  panel.title:SetPoint("LEFT", strip, "LEFT", 9, 0)
  panel.title:SetText(title or "")
  panel.note = self:Text(strip, "GameFontHighlightSmall", "RIGHT")
  panel.note:SetPoint("RIGHT", strip, "RIGHT", -9, 0)
  return panel
end

-- A row background (three-slice) across `frame`.
function Skin:RowBackground(frame, height)
  return self:Slice3(frame, "row", height, "BACKGROUND")
end
